WITH supplier_stats AS (SELECT supplier_id, COUNT(DISTINCT stock_qty) AS unique_categorys, COUNT(*) AS num_products FROM products GROUP BY supplier_id) SELECT suppliers.city, suppliers.supplier_name, supplier_stats.unique_categorys, supplier_stats.num_products FROM suppliers JOIN supplier_stats ON suppliers.id = supplier_stats.supplier_id WHERE supplier_stats.unique_categorys > 5 ORDER BY suppliers.city DESC, supplier_stats.num_products DESC;
